#!/usr/bin/env bash
# The terminal sessions quoted in lesson 22 of nosql-operations, as a script
# that produces them.
#
# THE SCRIPT IS THE SOURCE AND ITS OUTPUT IS NOT COMMITTED. Every transcript in
# this lesson was copied from running it.
#
#   sudo bash ../../lab.sh tools     # once
#   bash captures.sh
#
# Nothing is staged beyond lesson 1's `nosql` network, created here without
# showing it. The SQL files are the fences of postgres-does-that.md, taken back
# out of it, and every row in them is generated by the SQL itself. The crash is
# `docker kill`, run as shown. Container ids, log timestamps and WAL positions
# are whatever the run produced.
#
# Recorded on Ubuntu 24.04, Docker Engine 29.8, TZ=America/Sao_Paulo.
. "$(dirname "$0")/../../capture.sh"

ready_pg() {
  local i
  for i in $(seq 60); do
    docker exec postgres pg_isready -U postgres >/dev/null 2>&1 &&
      docker exec postgres psql -U postgres -c 'SELECT 1' >/dev/null 2>&1 && return 0
    sleep 1
  done
  echo "ready_pg: never answered" >&2; exit 1
}

quiet 'docker network create nosql'

block pg-start
run "$(from postgres-does-that.md 'docker run -d --name postgres --network nosql -e POSTGRES_PASSWORD=lab postgres:16')"
quiet 'ready_pg'; quiet 'sleep 3'; quiet 'ready_pg'
run 'docker exec postgres psql -U postgres -c "SELECT version()"'

block documents
from postgres-does-that.md '-- documents.sql: the shop'"'"'s orders as JSON documents, in one column' > documents.sql
run 'docker exec -i postgres psql -U postgres -a < documents.sql'

block keyvalue
from postgres-does-that.md '-- keyvalue.sql: a counter, and a cache that does not need to survive a crash' > keyvalue.sql
run 'docker exec -i postgres psql -U postgres -a < keyvalue.sql'

block crash
run 'docker kill postgres'
run 'docker start postgres'
quiet 'ready_pg'
run 'docker exec postgres psql -U postgres -c "SELECT (SELECT count(*) FROM page_views) AS page_views, (SELECT count(*) FROM cache) AS cache"'
run 'docker logs postgres 2>&1 | grep -E "not properly shut down|redo done|ready to accept" | tail -3'

block queue
from postgres-does-that.md '-- queue.sql: three jobs, for workers that must not take the same one' > queue.sql
run 'docker exec -i postgres psql -U postgres -q < queue.sql'
run "docker exec -d postgres psql -U postgres -c \"BEGIN; SELECT id FROM jobs WHERE NOT done ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED; SELECT pg_sleep(30); COMMIT;\""
quiet 'sleep 2'
run "docker exec postgres psql -U postgres -c \"SELECT id, task FROM jobs WHERE NOT done ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED\""
run "docker exec postgres psql -U postgres -c \"SELECT locktype, relation::regclass, mode, granted FROM pg_locks WHERE relation = 'jobs'::regclass\""
